**`src/components/ErrorBoundary.tsx`**

```tsx
import React, { Component, ErrorInfo, ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: (props: FallbackProps) => ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
  errorInfo: ErrorInfo | null;
}

export interface FallbackProps {
  error: Error;
  errorInfo: ErrorInfo;
  retry: () => void;
}

function DefaultFallback({ error, errorInfo, retry }: FallbackProps) {
  const [expanded, setExpanded] = React.useState(false);

  return (
    <div role="alert" style={styles.container}>
      <div style={styles.card}>
        <h2 style={styles.heading}>Something went wrong</h2>
        <p style={styles.message}>{error.message}</p>

        <button onClick={retry} style={styles.retryButton}>
          Try again
        </button>

        <button
          onClick={() => setExpanded((x) => !x)}
          style={styles.detailsToggle}
        >
          {expanded ? "Hide" : "Show"} details
        </button>

        {expanded && (
          <pre style={styles.stack}>
            {error.stack}
            {"\n\nComponent stack:"}
            {errorInfo.componentStack}
          </pre>
        )}
      </div>
    </div>
  );
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null, errorInfo: null };

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    this.setState({ errorInfo });
    this.props.onError?.(error, errorInfo);
    logError(error, errorInfo);
  }

  retry = () => {
    this.setState({ error: null, errorInfo: null });
  };

  render() {
    const { error, errorInfo } = this.state;

    if (error && errorInfo) {
      const fallbackProps: FallbackProps = { error, errorInfo, retry: this.retry };
      return this.props.fallback
        ? this.props.fallback(fallbackProps)
        : <DefaultFallback {...fallbackProps} />;
    }

    return this.props.children;
  }
}

function logError(error: Error, info: ErrorInfo) {
  console.group("[ErrorBoundary] Render error caught");
  console.error("Error:", error);
  console.error("Component stack:", info.componentStack);
  console.groupEnd();
}

const styles: Record<string, React.CSSProperties> = {
  container: {
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    minHeight: "100%",
    padding: "2rem",
    backgroundColor: "#f9fafb",
  },
  card: {
    maxWidth: 480,
    width: "100%",
    backgroundColor: "#fff",
    border: "1px solid #fee2e2",
    borderRadius: 8,
    padding: "2rem",
    boxShadow: "0 1px 3px rgba(0,0,0,.1)",
  },
  heading: {
    margin: "0 0 .5rem",
    fontSize: "1.25rem",
    color: "#991b1b",
  },
  message: {
    margin: "0 0 1.5rem",
    color: "#374151",
    wordBreak: "break-word",
  },
  retryButton: {
    display: "inline-block",
    marginRight: "1rem",
    padding: ".5rem 1.25rem",
    backgroundColor: "#2563eb",
    color: "#fff",
    border: "none",
    borderRadius: 6,
    cursor: "pointer",
    fontSize: "0.875rem",
  },
  detailsToggle: {
    display: "inline-block",
    padding: ".5rem 1.25rem",
    backgroundColor: "transparent",
    color: "#6b7280",
    border: "1px solid #d1d5db",
    borderRadius: 6,
    cursor: "pointer",
    fontSize: "0.875rem",
  },
  stack: {
    marginTop: "1rem",
    padding: "1rem",
    backgroundColor: "#f3f4f6",
    borderRadius: 4,
    fontSize: "0.75rem",
    overflowX: "auto",
    whiteSpace: "pre-wrap",
    wordBreak: "break-all",
    color: "#374151",
  },
};
```

---

## Key design decisions

| Decision | Rationale |
|---|---|
| Class component | `componentDidCatch` has no hook equivalent — error boundaries must be classes |
| `getDerivedStateFromError` + `componentDidCatch` | Former triggers re-render with error state; latter is where you log/report (has `errorInfo`) |
| `errorInfo` stored in state | Needed so the fallback can render the component stack |
| `retry` resets both `error` and `errorInfo` | Resetting only `error` would leave stale component stack on next failure |
| `fallback` render prop | Lets callers supply custom UI without sacrificing the built-in retry wiring |
| `onError` callback | Clean hook for sending to Sentry/Datadog without coupling the component to any SDK |

---

## Usage examples

**Basic wrapping:**
```tsx
<ErrorBoundary>
  <MyWidget />
</ErrorBoundary>
```

**With error reporting (e.g. Sentry):**
```tsx
<ErrorBoundary onError={(err, info) => Sentry.captureException(err, { extra: info })}>
  <Dashboard />
</ErrorBoundary>
```

**Custom fallback UI:**
```tsx
<ErrorBoundary
  fallback={({ error, retry }) => (
    <div>
      <p>Oops: {error.message}</p>
      <button onClick={retry}>Reload section</button>
    </div>
  )}
>
  <Chart />
</ErrorBoundary>
```

---

## What to watch out for

- **Granularity** — wrap isolated sections (a widget, a route) rather than the entire app so one failure doesn't blank the whole page.
- **Retry limits** — if the error is deterministic (bad data, broken import), retrying will loop forever. Add a `maxRetries` prop and a "reload page" escape hatch for production use.
- **Event handlers** — errors thrown inside `onClick` / `setTimeout` are **not** caught by error boundaries; handle those with `try/catch` or a global `window.onerror` listener.
- **Server-side rendering** — `componentDidCatch` is client-only; SSR frameworks (Next.js) have separate `error.tsx` conventions that complement this.
